<section class="container page-heading"><span class="section-kicker">Operasional studio</span><h1>Kelola reservasi</h1><p>Tinjau pesanan, pantau status pembayaran, dan tetapkan fotografer hanya setelah reservasi dikonfirmasi.</p></section>
<section class="container admin-page"><div class="surface"><div class="surface-pad page-toolbar"><div><h2 class="h5 mb-1">Daftar reservasi</h2><p class="form-note mb-0">Penugasan memeriksa bentrok jadwal studio dan fotografer di sisi server.</p></div><form method="get" class="d-flex gap-2 align-items-center"><input type="hidden" name="r" value="admin-reservations"><select name="status" class="form-select form-select-sm"><option value="">Semua status</option><?php foreach (['menunggu_pembayaran','menunggu_verifikasi','dikonfirmasi','sedang_foto','selesai','ditolak','dibatalkan'] as $s): ?><option value="<?= e($s) ?>" <?= $filterStatus===$s?'selected':'' ?>><?= e(status_label($s)) ?></option><?php endforeach; ?></select><button class="btn btn-sm btn-outline-dark">Filter</button></form></div><div class="table-wrap"><table class="table"><thead><tr><th>Reservasi / pelanggan</th><th>Jadwal</th><th>Pembayaran</th><th>Status</th><th>Penugasan / aksi</th></tr></thead><tbody><?php foreach ($reservations as $r): ?><tr><td><strong><?= e($r['kode_reservasi']) ?></strong><span class="subtext"><?= e($r['nama_paket']) ?></span><span class="subtext"><?= e($r['nama_pelanggan']) ?></span></td><td><?= e(date_id($r['tanggal_sesi'])) ?><span class="subtext"><?= e(substr((string)$r['jam_sesi'],0,5)) ?> · <?= (int)$r['durasi_menit_snapshot'] ?> menit</span></td><td><strong><?= money($r['total_terbayar']) ?></strong><span class="subtext">dari <?= money($r['harga_paket_snapshot']) ?> disetujui</span></td><td><span class="badge-status <?= e(status_class($r['status'])) ?>"><?= e(status_label($r['status'])) ?></span></td><td style="min-width:235px"><div class="d-grid gap-2"><form method="post" action="<?= e(url('admin-reservation-action')) ?>" class="d-flex gap-1"><?= csrf_field() ?><input type="hidden" name="action" value="assign"><input type="hidden" name="id_reservasi" value="<?= (int)$r['id_reservasi'] ?>"><select name="id_fotografer" class="form-select form-select-sm" required aria-label="Pilih fotografer"><option value="">Pilih fotografer</option><?php foreach ($photographers as $f): ?><option value="<?= (int)$f['id_pengguna'] ?>" <?= (int)$r['id_fotografer']===(int)$f['id_pengguna']?'selected':'' ?>><?= e($f['nama']) ?></option><?php endforeach; ?></select><button class="btn btn-sm btn-copper" type="submit" <?= $r['status']!=='dikonfirmasi'?'disabled title="Reservasi harus dikonfirmasi lebih dahulu"':'' ?>>Tugaskan</button></form><?php if ($r['id_fotografer']): ?><small class="muted">Fotografer: <?= e($r['nama_fotografer']) ?></small><?php endif; ?><?php if (!in_array($r['status'],['selesai','ditolak','dibatalkan'],true)): ?><form method="post" action="<?= e(url('admin-reservation-action')) ?>" class="d-flex gap-1"><?= csrf_field() ?><input type="hidden" name="id_reservasi" value="<?= (int)$r['id_reservasi'] ?>"><button class="btn btn-sm btn-outline-danger" name="action" value="reject" type="submit" data-confirm="Tolak reservasi <?= e($r['kode_reservasi']) ?>?">Tolak</button><button class="btn btn-sm btn-outline-secondary" name="action" value="cancel" type="submit" data-confirm="Batalkan reservasi <?= e($r['kode_reservasi']) ?>?">Batalkan</button></form><?php endif; ?></div></td></tr><?php endforeach; ?><?php if (!$reservations): ?><tr><td colspan="5" class="muted text-center py-5">Belum ada reservasi untuk filter ini.</td></tr><?php endif; ?></tbody></table></div></div></section>
